1	package config
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"path/filepath"
8		"sort"
9		"strings"
10		"time"
11	
12		"github.com/joelmoss/workroom/internal/errs"
13	)
14	
15	const DefaultWorkroomsDir = "~/workrooms"
16	
17	// DefaultChannel is the release channel used when none is configured.
18	const DefaultChannel = "stable"
19	
20	// reservedKeys are top-level config keys that hold scalar settings, not project
21	// entries. Every project enumerator already skips non-map values, so these are
22	// naturally excluded from listings; this set is the single source of truth for
23	// the places that must guard by name (e.g. RemoveProject).
24	var reservedKeys = map[string]bool{
25		"workrooms_dir": true,
26		"channel":       true,
27	}
28	
29	// isReserved reports whether key is a reserved scalar setting rather than a project path.
30	func isReserved(key string) bool { return reservedKeys[key] }
31	
32	// Config manages the workroom configuration stored at ~/.config/workroom/config.json.
33	type Config struct {
34		path string
35	}
36	
37	// New creates a Config. If configPath is empty, uses the default location.
38	func New(configPath string) (*Config, error) {
39		if configPath == "" {
40			home, err := os.UserHomeDir()
41			if err != nil {
42				return nil, fmt.Errorf("determine home directory: %w", err)
43			}
44			configPath = filepath.Join(home, ".config", "workroom", "config.json")
45		}
46		return &Config{path: configPath}, nil
47	}
48	
49	// Path returns the config file path.
50	func (c *Config) Path() string {
51		return c.path
52	}
53	
54	// Read returns the config data as a map, or an empty map if the file doesn't exist.
55	func (c *Config) Read() (map[string]any, error) {
56		data, err := os.ReadFile(c.path)
57		if err != nil {
58			if os.IsNotExist(err) {
59				return map[string]any{}, nil
60			}
61			return nil, fmt.Errorf("%w %s: %v", errs.ErrConfigRead, c.path, err)
62		}
63		var result map[string]any
64		if err := json.Unmarshal(data, &result); err != nil {
65			return nil, fmt.Errorf("%w %s: %v", errs.ErrConfigRead, c.path, err)
66		}
67		return result, nil
68	}
69	
70	// Write persists the config data to disk atomically (temp file + rename) so a
71	// concurrent reader never observes a truncated or partial file.
72	func (c *Config) Write(data map[string]any) error {
73		dir := filepath.Dir(c.path)
74		if err := os.MkdirAll(dir, 0o755); err != nil {
75			return fmt.Errorf("%w: create config directory %s: %v", errs.ErrConfigWrite, dir, err)
76		}
77		b, err := json.MarshalIndent(data, "", "  ")
78		if err != nil {
79			return fmt.Errorf("%w: marshal config: %v", errs.ErrConfigWrite, err)
80		}
81	
82		tmp, err := os.CreateTemp(dir, ".config-*.json.tmp")
83		if err != nil {
84			return fmt.Errorf("%w: create temp file: %v", errs.ErrConfigWrite, err)
85		}
86		tmpName := tmp.Name()
87		cleanup := func() { _ = os.Remove(tmpName) }
88	
89		if _, err := tmp.Write(b); err != nil {
90			tmp.Close()
91			cleanup()
92			return fmt.Errorf("%w %s: %v", errs.ErrConfigWrite, tmpName, err)
93		}
94		if err := tmp.Sync(); err != nil {
95			tmp.Close()
96			cleanup()
97			return fmt.Errorf("%w %s: %v", errs.ErrConfigWrite, tmpName, err)
98		}
99		if err := tmp.Close(); err != nil {
100			cleanup()
101			return fmt.Errorf("%w %s: %v", errs.ErrConfigWrite, tmpName, err)
102		}
103		if err := os.Chmod(tmpName, 0o644); err != nil {
104			cleanup()
105			return fmt.Errorf("%w %s: %v", errs.ErrConfigWrite, tmpName, err)
106		}
107		if err := os.Rename(tmpName, c.path); err != nil {
108			cleanup()
109			return fmt.Errorf("%w %s: %v", errs.ErrConfigWrite, c.path, err)
110		}
111		return nil
112	}
113	
114	// withLock runs fn while holding a best-effort cross-process advisory lock on the
115	// config (an exclusive sidecar lock file). It serialises read-modify-write cycles
116	// between the standalone CLI and the desktop app's bundled binary. It is
117	// best-effort: on any lock-acquisition trouble it degrades to running fn unlocked
118	// rather than failing the operation, and it steals a stale lock left by a crashed
119	// process.
120	func (c *Config) withLock(fn func() error) error {
121		lockPath := c.path + ".lock"
122		if err := os.MkdirAll(filepath.Dir(lockPath), 0o755); err != nil {
123			return fn()
124		}
125		const staleAfter = 10 * time.Second
126		for range 200 {
127			f, err := os.OpenFile(lockPath, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o644)
128			if err == nil {
129				f.Close()
130				defer func() { _ = os.Remove(lockPath) }()
131				return fn()
132			}
133			if !os.IsExist(err) {
134				// Cannot create the lock for some other reason; proceed unlocked.
135				return fn()
136			}
137			if info, e := os.Stat(lockPath); e == nil && time.Since(info.ModTime()) > staleAfter {
138				_ = os.Remove(lockPath) // steal a stale lock from a crashed process
139				continue
140			}
141			time.Sleep(10 * time.Millisecond)
142		}
143		// Gave up waiting (~2s); proceed unlocked rather than block forever.
144		return fn()
145	}
146	
147	// CanonicalPath resolves a path to an absolute, symlink-evaluated form so that
148	// the same project referenced via a symlink or trailing slash maps to one key.
149	// A leading ~ (or ~/) is expanded to the user's home directory first — a shell
150	// does this before a program sees the path, but a path typed into the app's New
151	// Project dialog reaches the CLI raw. If the path does not exist (EvalSymlinks
152	// fails), the absolute form is returned.
153	func CanonicalPath(p string) (string, error) {
154		expanded, err := expandTilde(p)
155		if err != nil {
156			return "", err
157		}
158		abs, err := filepath.Abs(expanded)
159		if err != nil {
160			return "", err
161		}
162		if resolved, err := filepath.EvalSymlinks(abs); err == nil {
163			return resolved, nil
164		}
165		return abs, nil
166	}
167	
168	// expandTilde expands a leading "~" or "~/" to the user's home directory. Other
169	// forms (e.g. "~user") are left untouched — only the current user's home is
170	// resolved.
171	func expandTilde(p string) (string, error) {
172		if p != "~" && !strings.HasPrefix(p, "~/") {
173			return p, nil
174		}
175		home, err := os.UserHomeDir()
176		if err != nil {
177			return "", err
178		}
179		if p == "~" {
180			return home, nil
181		}
182		return filepath.Join(home, p[2:]), nil
183	}
184	
185	// AddWorkroom adds a workroom entry under the given parent project path.
186	func (c *Config) AddWorkroom(parentPath, name, workroomPath, vcs string) error {
187		return c.withLock(func() error {
188			data, err := c.Read()
189			if err != nil {
190				return err
191			}
192	
193			project, ok := data[parentPath].(map[string]any)
194			if !ok {
195				project = map[string]any{"vcs": vcs, "workrooms": map[string]any{}}
196				data[parentPath] = project
197			}
198			project["vcs"] = vcs
199	
200			workrooms, ok := project["workrooms"].(map[string]any)
201			if !ok {
202				workrooms = map[string]any{}
203				project["workrooms"] = workrooms
204			}
205			workrooms[name] = map[string]any{"path": workroomPath}
206	
207			return c.Write(data)
208		})
209	}
210	
211	// AddProject registers a project with no workrooms (idempotent). An existing
212	// project's workrooms are never clobbered; only its vcs is refreshed.
213	func (c *Config) AddProject(parentPath, vcs string) error {
214		return c.withLock(func() error {
215			data, err := c.Read()
216			if err != nil {
217				return err
218			}
219			if project, ok := data[parentPath].(map[string]any); ok {
220				project["vcs"] = vcs
221				if _, ok := project["workrooms"].(map[string]any); !ok {
222					project["workrooms"] = map[string]any{}
223				}
224			} else {
225				data[parentPath] = map[string]any{"vcs": vcs, "workrooms": map[string]any{}}
226			}
227			return c.Write(data)
228		})
229	}
230	
231	// SetProjectVCS updates the stored vcs type for an already-registered project. It is a
232	// no-op (returning nil) if the project isn't in the config — it never creates a project,
233	// and it preserves the project's workrooms map. Used to reconcile the persisted type when
234	// a project's on-disk VCS has changed (e.g. a colocated jj repo whose .jj dir was removed,
235	// leaving plain git); see Service.effectiveVCS.
236	func (c *Config) SetProjectVCS(parentPath, vcs string) error {
237		return c.withLock(func() error {
238			data, err := c.Read()
239			if err != nil {
240				return err
241			}
242			project, ok := data[parentPath].(map[string]any)
243			if !ok {
244				return nil
245			}
246			project["vcs"] = vcs
247			return c.Write(data)
248		})
249	}
250	
251	// RemoveWorkroom removes a workroom entry. If the parent has no remaining workrooms, it is removed.
252	func (c *Config) RemoveWorkroom(parentPath, name string) error {
253		return c.withLock(func() error {
254			data, err := c.Read()
255			if err != nil {
256				return err
257			}
258	
259			project, ok := data[parentPath].(map[string]any)
260			if !ok {
261				return nil
262			}
263	
264			workrooms, ok := project["workrooms"].(map[string]any)
265			if !ok {
266				return nil
267			}
268	
269			delete(workrooms, name)
270	
271			if len(workrooms) == 0 {
272				delete(data, parentPath)
273			}
274	
275			return c.Write(data)
276		})
277	}
278	
279	// RemoveWorkroomKeepProject removes a workroom entry but leaves the parent project
280	// registered even when it has no remaining workrooms. Used by GUI callers that pin
281	// empty projects in the sidebar.
282	func (c *Config) RemoveWorkroomKeepProject(parentPath, name string) error {
283		return c.withLock(func() error {
284			data, err := c.Read()
285			if err != nil {
286				return err
287			}
288	
289			project, ok := data[parentPath].(map[string]any)
290			if !ok {
291				return nil
292			}
293	
294			workrooms, ok := project["workrooms"].(map[string]any)
295			if !ok {
296				return nil
297			}
298	
299			delete(workrooms, name)
300	
301			return c.Write(data)
302		})
303	}
304	
305	// RemoveProject removes a project entry (and its nested workrooms map) from the
306	// config. It does NOT touch the filesystem or VCS — any worktree/workspace teardown
307	// is the caller's job (via Service.Delete). Idempotent: an absent project is a no-op
308	// returning nil. Reserved scalar keys (e.g. "workrooms_dir", "channel") are never
309	// deletable through here.
310	func (c *Config) RemoveProject(parentPath string) error {
311		return c.withLock(func() error {
312			data, err := c.Read()
313			if err != nil {
314				return err
315			}
316			if isReserved(parentPath) {
317				return nil // reserved key, not a project
318			}
319			delete(data, parentPath)
320			return c.Write(data)
321		})
322	}
323	
324	// WorkroomNames returns the names of every workroom registered under the given
325	// project path, sorted for deterministic ordering. An unknown project or one with
326	// no workrooms yields an empty slice (never nil-panics). The reserved
327	// "workrooms_dir" key is treated as having no workrooms.
328	func (c *Config) WorkroomNames(parentPath string) ([]string, error) {
329		data, err := c.Read()
330		if err != nil {
331			return nil, err
332		}
333		project, ok := data[parentPath].(map[string]any)
334		if !ok {
335			return []string{}, nil
336		}
337		workrooms, ok := project["workrooms"].(map[string]any)
338		if !ok {
339			return []string{}, nil
340		}
341		names := make([]string, 0, len(workrooms))
342		for name := range workrooms {
343			names = append(names, name)
344		}
345		sort.Strings(names)
346		return names, nil
347	}
348	
349	// FindCurrentProject finds the project for the given directory. If cwd is a project path in the
350	// config, returns it directly. Otherwise checks if cwd is a workroom path under any project.
351	// Returns (projectPath, projectData, found).
352	func (c *Config) FindCurrentProject(cwd string) (string, map[string]any, bool) {
353		data, err := c.Read()
354		if err != nil {
355			return cwd, nil, false
356		}
357	
358		if project, ok := data[cwd].(map[string]any); ok {
359			return cwd, project, true
360		}
361	
362		for projectPath, v := range data {
363			project, ok := v.(map[string]any)
364			if !ok {
365				continue
366			}
367			workrooms, ok := project["workrooms"].(map[string]any)
368			if !ok {
369				continue
370			}
371			for _, info := range workrooms {
372				infoMap, ok := info.(map[string]any)
373				if !ok {
374					continue
375				}
376				if infoMap["path"] == cwd {
377					return projectPath, project, true
378				}
379			}
380		}
381	
382		return cwd, nil, false
383	}
384	
385	// ProjectsWithWorkrooms returns all projects that have at least one workroom.
386	func (c *Config) ProjectsWithWorkrooms() (map[string]map[string]any, error) {
387		data, err := c.Read()
388		if err != nil {
389			return nil, err
390		}
391	
392		result := map[string]map[string]any{}
393		for path, v := range data {
394			project, ok := v.(map[string]any)
395			if !ok {
396				continue
397			}
398			workrooms, ok := project["workrooms"].(map[string]any)
399			if !ok || len(workrooms) == 0 {
400				continue
401			}
402			result[path] = project
403		}
404		return result, nil
405	}
406	
407	// AllProjects returns every registered project, including those with zero
408	// workrooms. Non-project top-level keys (e.g. workrooms_dir) are skipped.
409	func (c *Config) AllProjects() (map[string]map[string]any, error) {
410		data, err := c.Read()
411		if err != nil {
412			return nil, err
413		}
414	
415		result := map[string]map[string]any{}
416		for path, v := range data {
417			project, ok := v.(map[string]any)
418			if !ok {
419				continue
420			}
421			result[path] = project
422		}
423		return result, nil
424	}
425	
426	// WorkroomsDir returns the configured workrooms directory, or the default ~/workrooms.
427	func (c *Config) WorkroomsDir() (string, error) {
428		data, err := c.Read()
429		if err != nil {
430			return expandPath(DefaultWorkroomsDir)
431		}
432	
433		if dir, ok := data["workrooms_dir"].(string); ok && dir != "" {
434			return expandPath(dir)
