import Foundation

/// Shared, app-wide project data: the project list plus everything derived from it that is
/// identical across windows — root branch/bookmark labels, the VCS/CI status cache, GitHub-CLI
/// availability, and the in-flight project busy set. Extracted from `AppStore` (issue #70) so that
/// multiple per-window `AppStore`s can share one project list while each keeps its own selection,
/// terminals, splits, history, and run state.
///
/// This first step is **storage-only and behaviour-preserving**: `AppStore` proxies these
/// properties straight through to here and re-publishes the store's `objectWillChange`, so the
/// single shared `AppStore` still behaves exactly as before. The CLI/load logic stays on `AppStore`
/// for now (it mutates these via the proxies); per-window construction and the multi-window wiring
/// land in a follow-up.
@MainActor
final class ProjectStore: ObservableObject {
  /// The shared instance used in production (every window's `AppStore` points at it). Tests
  /// construct an isolated `AppStore()`, which gets its own fresh `ProjectStore`, so they never
  /// pollute this singleton or each other.
  static let shared = ProjectStore()

  /// The list of configured projects (from the CLI's `~/.config/workroom/config.json`). The one
  /// piece of state shared across all windows.
  @Published var projects: [Project] = []

  /// Per-project resolved root branch/bookmark labels, hydrated asynchronously after each load.
  @Published var rootRefs: [Project.ID: RootRef] = [:]

  /// Per-workroom (and per-root) VCS + CI status driving the ambient badges and the Changes panel
  /// (issue #24), keyed by `SidebarID`. Resolved app-side, best-effort/"last checked". Shared so two
  /// windows showing the same workroom report a consistent badge and don't double the probes.
  @Published var workroomStatuses: [SidebarID: WorkroomStatus] = [:]

  /// Whether the GitHub CLI is usable for the PR/CI probes (machine-global). Optimistic default so
  /// no warning flashes before the first check.
  @Published var githubCLIStatus: GitHubCLIStatus = .available

  /// Owns the `gh auth status` probe: its freshness clock AND its single-flight, so N windows share
  /// one `gh` and the staleness check can't interleave with the write the way a bare timestamp on
  /// this class did. `githubCLIStatus` above is the SwiftUI-observable mirror of what it decided.
  ///
  /// A `var` purely so tests can swap in an instance with millisecond TTLs; production never
  /// reassigns it.
  var ghAuthCache = GitHubAuthCache()

  /// Project paths with an in-flight create/delete (for per-row progress + disabling).
  @Published var busyProjects: Set<String> = []

  /// Target ids of workrooms whose create is still in flight — from the "created" event until the
  /// create flow ends (issue #116). A workroom here must not be deleted: its setup script is running
  /// against the worktree. Shared across windows so a delete from ANY window is blocked, not just the
  /// creating one.
  @Published var creatingWorkrooms: Set<TerminalTarget.ID> = []

  /// Sidebar rows with a commit in flight, for the per-row button state.
  ///
  /// Shared across windows for the reason `creatingWorkrooms` is: `AppStore` is per WINDOW, but
  /// `JJSnapshotGate` and the `index.lock` contention it exists to prevent are per PROCESS. Held on
  /// the window's own store, a second window's 15s sweep, FSEvents lane and Refresh button all saw an
  /// empty set and kept probing a repo mid-write.
  @Published var committingTargets: Set<SidebarID> = []

  /// How many commits are in flight against each project root, which is what the read lanes actually
  /// have to stand clear of.
  ///
  /// Keyed by project root, not by row: the gate serializes on the project root, and a git worktree's
  /// index and refs live in the MAIN repo — so a commit in workroom A contends with a status probe of
  /// workroom B of the same project, which a per-row check waved straight through. Counted rather than
  /// a `Set` because the app's premise is N parallel workrooms, so two of one project can legitimately
  /// commit at once and the first to finish must not clear the other's suppression.
  @Published var committingProjectRoots: [String: Int] = [:]

  /// Target ids of workrooms with an in-flight optimistic deletion — dropped from the sidebar but
  /// their teardown (worktree/config removal) not yet finished. `AppStore.apply` filters these out of
  /// every incoming CLI `list`, so a stale snapshot taken before the teardown persisted can't
  /// resurrect a just-deleted workroom (the create/delete reload race). Cleared when teardown ends.
  @Published var deletingWorkrooms: Set<TerminalTarget.ID> = []

  /// Whether the persisted last-session selection is still up for grabs (issue #70). The first
  /// window to launch with `restore == true` consumes it and restores the saved selection; every
  /// other window — including every ⌘N window — gets `false` and so starts blank.

}

// MARK: Derived

/// The in-flight action IF it belongs to the workroom currently on screen — what the toolbar renders.
///
/// Distinct from `inFlight`, which is the model-wide lock and is what `canFetch`/`canPush`/`canPull`
/// gate on: a second action must be blocked even when it was started from another workroom, because
/// the writer and the gate are shared. Only the LABEL is per-target.
var activeAction: VCSRemoteAction? { inFlightTarget == target ? inFlight : nil }

var canFetch: Bool { snapshot?.primaryRemote != nil && inFlight == nil }
var canPush: Bool { snapshot?.primaryRemote != nil && inFlight == nil }
/// Pull needs something to pull FROM: a counterpart that exists on the remote.
var canPull: Bool {
  guard snapshot?.primaryRemote != nil, inFlight == nil else { return false }
  guard let tracking = snapshot?.tracking else { return false }
  return !tracking.gone
}

func canPerform(_ action: VCSRemoteAction) -> Bool {
  switch action {
  case .fetch: return canFetch
  case .push: return canPush
  case .pull: return canPull
  case .abortRebase: return inFlight == nil
  }
}

// MARK: Actions

/// Perform an action. Dropped if one is already in flight — the model is deliberately single-action
/// so a double-click can't fire twice and Push can't race Pull.
///
/// `anonymousRevision` matters only for a jj workroom whose `@` carries no bookmark: pushing a bare
/// `@` fails when the working copy is empty and undescribed, which is exactly the state a fresh
/// workroom sits in. Callers pass `CLIVCSWriter.jjPushRevision(hasChanges:hasDescription:)`.
///
/// `userInitiated` decides whether a failure gets a dialog. Only `autoFetchIfDue` passes `false`.
func perform(
  _ action: VCSRemoteAction, setUpstream: Bool = false, anonymousRevision: String = "@",
  userInitiated: Bool = true
) {
  guard inFlight == nil, let target, let snapshot else { return }
  // Aborting a rebase is purely local — requiring a remote would leave a workroom wedged in a rebase
  // with no way out from the UI, which is the one state where recovery matters most.
  let remote = snapshot.primaryRemote ?? ""
  if remote.isEmpty, action != .abortRebase {
    lastFailure = .noRemote
    lastAction = action
    if userInitiated { raiseFailureReport(.noRemote, action: action) }
    return
  }
  inFlight = action
  inFlightTarget = target
  lastAction = action
  lastFailure = nil
  failureReport = nil
  lastPullConflicted = false
  let makeWriter = self.makeWriter
  let current = snapshot.current
  let tracking = snapshot.tracking
  actionTask = Task { [weak self] in
    let root = URL(fileURLWithPath: target.path, isDirectory: true)
    let result: VCSRemoteActionResult
    do {
      let writer = try makeWriter(root)
      switch action {
      case .fetch:
        result = await writer.fetch(
          path: target.path, projectRoot: target.projectRoot, remote: remote)
      case .push:
        result = await writer.push(
          path: target.path, projectRoot: target.projectRoot, current: current, remote: remote,
          setUpstream: setUpstream, anonymousRevision: anonymousRevision)
      case .pull:
        result = await writer.pullRebase(
          path: target.path, projectRoot: target.projectRoot, current: current, remote: remote,
          tracking: tracking)
      case .abortRebase:
        result = await writer.abortRebase(path: target.path, projectRoot: target.projectRoot)
      }
    } catch {
      result = .failed(.other("\(error)"))
    }
    self?.finish(action, result: result, for: target, userInitiated: userInitiated)
  }
}

private func finish(
  _ action: VCSRemoteAction, result: VCSRemoteActionResult, for target: Target,
  userInitiated: Bool
) {
  // Always cleared: the action really is over, and this is the model-wide single-action lock. What is
  // NOT unconditional is the RESULT, below.
  inFlight = nil
  inFlightTarget = nil
  // The work happened in `target`'s repo whatever is selected now, so the fetch stamp and the
  // downstream refresh belong to it and fire regardless.
  if case .ok = result {
    if action == .fetch || action == .pull { recordOwnFetch(projectRoot: target.projectRoot) }
    onDidMutate?(action, target.sid)
  }
  // The DIALOG is deliberately raised ahead of the identity guard below. Something the user asked for
  // failed, and that fact belongs to them, not to the current selection: with the report behind the
  // guard, starting a push and switching workrooms mid-flight reported the failure nowhere at all —
  // no dialog, no toolbar notice, no record. The spinner stopped and nothing said why. The workroom is
  // named whenever it isn't the one on screen, so the dialog can't be misread as this one's failure.
  if case .failed(let failure) = result, userInitiated {
    raiseFailureReport(
      failure, action: action,
      workroom: self.target == target ? nil : describeTarget?(target.sid))
  }
  // Everything past here writes PUBLISHED state that the toolbar renders for whatever is selected NOW,
  // so it needs the same guard `apply` has. Without it, starting a push in one workroom and switching
  // to another put the first one's failure — and its action label — on the second one's toolbar,
  // reporting a failure for a workroom where nothing was attempted.
  guard self.target == target else { return }
  switch result {
  case .ok:

/// Why a remote read or action failed.
///
/// Deliberately NOT folded into `VCSError`: that enum is the backend-*read* taxonomy
/// (`lockContention`/`staleSnapshot`/`partialData`/…) and `WorkroomStatusResolver.failure(for:)`
/// switches over it exhaustively to choose a sidebar badge. `.authRequired` has no sidebar badge and
/// no sensible answer there, so adding it would force a meaningless decision in a function that
/// currently has a principled one for every case. Same reasoning that put `CIResolution`/`PRResolution`
/// beside their resolver instead of in `VCSModels.swift`.
enum VCSRemoteFailure: Equatable, Sendable {
  /// `git`/`jj` not on PATH. Distinct from `VCSToolVersions`' floor check, which runs at launch —
  /// this is the same condition caught at the point of use.
  case toolMissing(String)
  case timedOut(VCSRemoteAction)
  /// Credentials were needed and none were available.
  case authRequired(String)
  /// The host's key isn't in `known_hosts`. `BatchMode=yes` turns what would be an interactive
  /// confirmation into this, so it needs its own copy — telling the user to configure a credential
  /// helper would be wrong advice.
  case hostKeyUnverified(String)
  case noRemote
  /// Push rejected (non-fast-forward). The engine NEVER force-pushes; the UI offers Pull.
  case rejected(String)
  /// git refused because tracked files would be overwritten.
  case dirtyWorkingTree(String)
  /// A failed or killed `git pull --rebase` left `rebase-merge`/`rebase-apply` behind. The repo needs
  /// `git rebase --abort`, so the UI must offer that instead of a retry that will fail identically.
  case rebaseInProgress
  /// A repo lock was held — git `index.lock`/`packed-refs.lock`, or jj's `git_import_export.lock`.
  ///
  /// The payload is the lock file itself when we could find it on disk, and that distinction decides
  /// what the UI offers. **`nil` ⇒ transient contention**, so Retry is genuine: another command held the
  /// lock briefly and by the next click it is likely gone. **Non-nil ⇒ a lock file is sitting there
  /// right now**, and retrying fails identically every time — the same reasoning that makes
  /// `rebaseInProgress` offer Abort instead of Retry.
  ///
  /// A leftover lock is what a SIGKILLed git leaves: the runner escalates to `killTree` two seconds
  /// after SIGTERM, and SIGKILL cannot be caught, so git's own cleanup never runs.
  ///
  /// Workroom does NOT delete it. Whether a lock is truly abandoned or held by a git running right now
  /// is not knowable from outside the process — `lsof` can't be trusted for it, and removing a live
  /// lock corrupts the index — so this reports and explains, and the removal stays the user's call.
  /// That is also what git's own message tells you to do.
  case locked(VCSLockFile?)
  /// jj refused to rewrite a commit protected by `immutable_heads()` — reached by Pull, whose
  /// `jj rebase -b @` moves the whole branch containing `@`, and that branch usually contains a
  /// remote-tracked commit. Measured on jj 0.43 for a workroom based off a feature branch while trunk
  /// moved on: `Error: Commit 4c8e754829da is immutable`.
  ///
  /// Offers no retry, for `rebaseInProgress`'s reason: the destination doesn't change between clicks, so
  /// every retry fails identically. The real fix is remembering each workroom's own base instead of
  /// guessing `trunk()` — filed, not built.
  case immutableHistory(String)
  /// jj refuses to push a commit with an empty description, changes or not. This is the state a workroom
  /// sits in the moment you edit a file and before you write a message, so it is the most reachable
  /// failure on the push path, not an edge case. Measured: `Error: Won't push commit 050e657d3c36 since
  /// it has no description`.
  case needsDescription(String)
  case other(String)
}

/// A VCS remote action queued behind a confirmation. Only a pull over a dirty working tree needs one:
/// `--autostash` stashes and reapplies, and workroom trees are essentially always dirty, so this fires
/// most times someone pulls — the copy has to be worth reading rather than a speed bump.
///
/// Carries the `SidebarID` it was raised for, and `AppStore.runRemoteAction` verifies it: the dialog is
/// not modal to the sidebar, so the selection can move while it is open.
struct PendingVCSAction: Identifiable, Equatable, Sendable {
  let action: VCSRemoteAction
  let sid: SidebarID
  var id: String { "\(action.rawValue)-\(sid.hashValue)" }

  case .authRequired:
    // The #1 expected failure. The runner sets GIT_TERMINAL_PROMPT=0 and ssh BatchMode, so this
    // fails instantly rather than hanging — but the raw stderr is baffling, hence bespoke copy.
    return "Couldn’t authenticate. Load your key into ssh-agent, or set a credential helper."
  case .hostKeyUnverified:
    return "The host’s key isn’t known. Connect once from a terminal to accept it."
  case .noRemote:
    return "No remote configured."
  case .rejected:
    return "Rejected — the remote has commits you don’t. Pull first."
  case .dirtyWorkingTree:
    return "Uncommitted changes are in the way. Commit or stash them first."
  case .rebaseInProgress:
    return "A rebase is in progress. Abort it to continue."
  case .locked(let file):
    // Two different facts, so two different sentences. Saying "busy, try again" over a lock file that
    // is still there sends the user round a loop that cannot terminate.
    guard let file else { return "The repository was busy. Try again." }
    return "A leftover \(file.filename) is blocking git."
  case .needsDescription:
    // The most reachable failure on the push path: this is every workroom between the first edit and
    // the first commit message. The remedy is one command, so name it.
    return "Describe the change before pushing it (jj describe)."
  case .immutableHistory:
