      case .abortRebase:
        result = await writer.abortRebase(path: target.path, projectRoot: target.projectRoot)
      }
    } catch {
      result = .failed(.other("\(error)"))
    }
    self?.finish(action, result: result, for: target, userInitiated: userInitiated)
  }
}

