  /// auth state, but the cost of a redundant local `--version` is cheap enough that a bespoke,
  /// longer TTL isn't worth its own tuning surface.
  private struct Slot {
    var cached: (status: VCSToolVersions.Status, at: ContinuousClock.Instant)?
    var inFlight: Task<VCSToolVersions.Status, Never>?
    /// Generation-stamped like `GitHubAuthCache`, so a superseded probe can't clear a newer flight
    /// or overwrite a newer verdict when it finally lands.
    var generation = 0
  }

