  /// that isn't actually an ancestor. See `VCSRemoteFailure.noKnownUpstream`. Always `false` for
  /// git and for a bookmarked jj `@`, where `trunk()` never enters the comparison at all.
  let noKnownUpstream: Bool

  init(comparedTo: String, ahead: Int?, behind: Int?, gone: Bool, noKnownUpstream: Bool = false) {
    self.comparedTo = comparedTo
    self.ahead = ahead
    self.behind = behind
    self.gone = gone
    self.noKnownUpstream = noKnownUpstream
  }
}

