/// **The bug T7 exists to close.** An unbookmarked `@` that has diverged from `trunk()` ENTIRELY
/// (not just fallen behind it) must report `noKnownUpstream`, not a wrong `behind` count. Verified
/// empirically first with plain jj (see the plan's T7 note): `trunk() & ::@` is empty once `main`
/// is moved to a disjoint root-based line, while the old `@..trunk()` still silently counted 1 —
/// a meaningless number, since the two histories share nothing but the repo root.
func testDivergedTrunkReportsNoKnownUpstreamNotAWrongCount() async throws {
  try requireTool("git")
  try requireTool("jj")
  guard let j = jjFixture() else { throw XCTSkip("jj fixture could not be created") }
  let env = "JJ_CONFIG=\(j.config)"

  // Our own unbookmarked work off the ORIGINAL main.
  sh("\(env) jj new main -m mine", in: j.project)
  let mine = sh("\(env) jj log --no-graph -r @ -T 'change_id.short()'", in: j.project)
    .out
    .trimmingCharacters(in: .whitespacesAndNewlines)

  // Move main sideways onto a totally disjoint line — sharing nothing with `mine` but the repo
  // root. `--allow-backwards` is required: jj otherwise refuses to move a bookmark to a commit
  // that isn't a descendant of where it was.
  sh("\(env) jj new 'root()' -m disjoint-main", in: j.project)
  sh("\(env) jj bookmark set main -r @ --allow-backwards", in: j.project)
  sh("\(env) jj git push --bookmark main", in: j.project)

  // Back onto our own (now-orphaned-from-main) work.
  sh("\(env) jj edit \(mine)", in: j.project)

  let s = try await state(writer("jj"), path: j.project, projectRoot: j.project)
  XCTAssertTrue(s.tracking?.noKnownUpstream == true, "trunk() is no longer an ancestor of @")
  XCTAssertNil(s.tracking?.behind, "must not report a count measured against an unrelated line")
}

