// scrollbar). Faded at rest, opaque on hover. Complements the ⌘↑/⌘↓ shortcuts in `keyDown`.
private let goToBottomSize: CGFloat = 28
private let goToBottomInset: CGFloat = 12
private let goToBottomButton = GoToBottomButton()

// OSC 9;4 progress safety timer (issue #28 follow-up): a program that reports it's working but never
// sends REMOVE — or a long-idle TUI — would otherwise pin the busy indicator on forever. It's a
// "declared busy but went silent" backstop, not a fixed time-since-last-report cutoff: while the
// program keeps repainting (title frames — see `handleTitleChange`) the timer is refreshed, so a long
// task doesn't stop spinning mid-run (issue #38). OSC 9;4 is edge-triggered — Claude emits it once at
// the start (and once at finish), Codex never — but both animate their title ~1–10×/s the whole time
// they work, so the title is the liveness heartbeat the progress signal itself lacks.
private var progressTimeoutTimer: Timer?
private var progressActive = false
private static let progressTimeout: TimeInterval = 30

/// How to fetch this pane's previous text, replayed once the surface exists (issue #144). Nil for a
/// pane that is not being restored, and cleared the moment it has been used.
///
/// A **closure, not the text**, and that is the point: restore materialises every target's tabs
/// eagerly (the sidebar's terminal subtree renders from them), so reading each sidecar up front
/// would do hundreds of file reads on the launch path and then hold every one of them — up to
/// 256KB per pane — in memory for the process's lifetime, including for panes that never mount.
/// Deferring to `createSurface` means only a pane you actually look at pays, and it pays once.
///
/// Set through `adoptRestoredScrollback` rather than `init` because views are built by the
/// `TerminalSessions.makeView` factory, whose signature is shared with every other spawn path.
private var restoredScrollback: (() -> String?)?
/// One replay per view, ever.
private var didReplayScrollback = false
/// Whether this pane has ever had more rows than fit on screen (issue #144), set from the
/// scrollbar geometry libghostty already pushes. The alternate-screen discriminator: see
/// `captureScrollback`.
private var everHadScrollback = false

init(workingDirectory: String, command: String? = nil, spawnsSurface: Bool = true) {
  self.workingDirectory = workingDirectory
  self.runCommand = command
  self.spawnsSurface = spawnsSurface
  super.init(frame: .zero)
  wantsLayer = true
  setupTrackingArea()
  setupScrollbar()
  setupGoToBottomButton()
  setupDragAndDrop()
  setAccessibilityRole(.textArea)
  // Stable id so UI tests can count on-screen panes (a surface only appears in the a11y tree while
  // it's actually mounted in a window — exactly the "is this pane rendering?" signal we need).
  setAccessibilityIdentifier("terminal.surface")
  let dir = URL(fileURLWithPath: workingDirectory).lastPathComponent
  setAccessibilityLabel(dir.isEmpty ? "Terminal" : "Terminal — \(dir)")
  // The find bar's only channel to the engine: every search action runs as a libghostty keybind
  // action on this surface.
  searchModel.perform = { [weak self] action in
    guard let self else { return }
    self.performBindingAction(action.bindingString)
    // Closing the bar (Esc / ✕) hands keyboard focus back to the terminal — otherwise first
    // responder is left on the now-removed search field (→ the window), and the next keystroke
    // wouldn't reach the shell until you clicked the pane.
    if action == .end { self.window?.makeFirstResponder(self) }
  }
}

@available(*, unavailable)
required init?(coder: NSCoder) { fatalError("init(coder:) is not supported") }

// MARK: Surface lifecycle (A1)

/// Whether a (re-)spawn should proceed now. One predicate gates every entry into `createSurface`
/// (window mount, background `ensureSurfaceCreated`, deferred `setFrameSize`/`layout`) so no path can
/// slip through: a torn-down view must NEVER re-spawn (issue #7 phantom respawn — SwiftUI can re-mount
/// a closed run tab's view, which would relaunch its command as an untracked dev server orphaned on
/// its port), a test view (`spawnsSurface == false`) stays surface-less, and an already-spawned one
/// isn't duplicated. Exposed so the lifecycle guards are unit-testable without a live libghostty surface.
var canSpawnSurface: Bool { !isTornDown && spawnsSurface && surface == nil }

private func createSurface() {
  guard canSpawnSurface, let app = GhosttyApp.shared.app else { return }
  guard let backingSize = backingPixelSize() else {
    pendingSurfaceCreation = true
    return
  }
  pendingSurfaceCreation = false

  var config = ghostty_surface_config_new()
  config.platform_tag = GHOSTTY_PLATFORM_MACOS
  config.platform = ghostty_platform_u(
    macos: ghostty_platform_macos_s(nsview: Unmanaged.passUnretained(self).toOpaque()))
  config.userdata = Unmanaged.passUnretained(self).toOpaque()
  config.scale_factor = Double(window?.backingScaleFactor ?? 2.0)
  config.context = GHOSTTY_SURFACE_CONTEXT_TAB  // Workroom: one surface per tab (no splits yet)

  // Spawn a login shell in the target directory. No explicit `command` → libghostty launches the
  // user's default shell as a login shell (matches Workroom's prior `startProcess(... -l)`).
  freeSurfaceCStrings()
  guard let cwd = strdup(workingDirectory) else { return }
  surfaceCStrings.append(cwd)
  config.working_directory = UnsafePointer(cwd)

  // Inject `TERMINFO` into the shell's environment so it can resolve the bundled `xterm-ghostty`
  // entry (libghostty sets `TERM` but not `TERMINFO`, and macOS has no system entry — without this
  // line editing such as Backspace breaks). Process-level `setenv` doesn't reach the child, so we
  // go through the surface config's env-var array, which libghostty applies to the spawned shell.
  if let terminfo = GhosttyApp.shared.terminfoDirectory,
    let key = strdup("TERMINFO"), let value = strdup(terminfo)
  {
    surfaceCStrings.append(key)
    surfaceCStrings.append(value)
    let buffer = UnsafeMutablePointer<ghostty_env_var_s>.allocate(capacity: 1)
    buffer[0] = ghostty_env_var_s(key: UnsafePointer(key), value: UnsafePointer(value))
    envVarsBuffer = buffer
    config.env_vars = buffer
    config.env_var_count = 1
  }

  // Run-command surface (issue #7): launch a specific command instead of the login shell and KEEP
  // the pane open after it exits (`wait_after_command`) so its output stays visible. The pointer
  // joins `surfaceCStrings`, freed on teardown like `working_directory` / the env vars above.
  if let runCommand, !runCommand.isEmpty, let cmd = strdup(runCommand) {
    surfaceCStrings.append(cmd)
    config.command = UnsafePointer(cmd)
    config.wait_after_command = true
  }

  surface = ghostty_surface_new(app, &config)
  guard let surface else {
    freeSurfaceCStrings()
    return
  }

  let scale = Double(window?.backingScaleFactor ?? 2.0)
  ghostty_surface_set_content_scale(surface, scale, scale)
  ghostty_surface_set_size(surface, backingSize.width, backingSize.height)
  applyColorScheme(isDark: Self.isCurrentAppearanceDark())
  if let screen = window?.screen ?? NSScreen.main,
    let displayID = screen.deviceDescription[NSDeviceDescriptionKey("NSScreenNumber")] as? UInt32
  {
    ghostty_surface_set_display_id(surface, displayID)
  }
  applyOcclusionState()
  // Keep the overlay scrollbar and go-to-bottom button above the surface's Metal content.
  addSubview(scrollbarThumb, positioned: .above, relativeTo: nil)
  addSubview(goToBottomButton, positioned: .above, relativeTo: nil)
  layoutGoToBottomButton()
  // The surface may have been created AFTER this view already became first responder: a zero-bounds
  // attach defers `createSurface` to `setFrameSize`/`layout`, so `becomeFirstResponder` ran while
  // `surface == nil` and its `setSurfaceFocused(true)` no-oped (see `setSurfaceFocused`). Without
  // this the surface comes up blurred while the view holds first responder — keys reach `keyDown`
  // but libghostty drops them on an unfocused surface, and a click can't recover because
  // `makeFirstResponder` short-circuits on an already-first-responder view. Re-sync the flag now.
  adoptFocusIfFirstResponder()
  // Replay the previous session's text (issue #144) synchronously, in the same main-thread call
  // that created the surface, so no IO callback can interleave ahead of it. The shell's own first
  // prompt may still land after the replayed block, which is correct — the divider separates
  // restored history from live output.
  replayRestoredScrollback()
}

/// Spawn the surface's PTY *without* waiting for window mount (issue #67, background run). Normally
/// `createSurface` fires from `viewDidMoveToWindow`, so a run tab that's started in the background and
/// never made active would never mount — and its command would never start (the toast would claim
/// "running" while nothing ran). `createSurface` only hard-requires positive bounds
/// (`backingPixelSize`); every window reference inside it is a soft fallback. So give the view a
/// non-zero frame and create the surface now; it re-sizes correctly when it later mounts into a real
/// pane. No-op if the surface already exists or this is a test view (`spawnsSurface == false`).
func ensureSurfaceCreated(initialSize: CGSize) {
  guard spawnsSurface, surface == nil else { return }
  if bounds.width <= 0 || bounds.height <= 0 {
    // Positive bounds are the one thing `createSurface` can't proceed without (it defers via
    // `pendingSurfaceCreation` otherwise). A sane initial size also gives the spawned command a
    // reasonable COLUMNS/LINES until the first on-window resize.
    let size =
      (initialSize.width > 0 && initialSize.height > 0)
      ? initialSize : CGSize(width: 800, height: 480)
    setFrameSize(size)
  }
  createSurface()
