243	  func performCommit(
244	    _ request: VCSCommitRequest, on sid: SidebarID,
245	    completion: @escaping (VCSCommitResult) -> Void
246	  ) {
247	    guard let item = selectedStatusWorkItem(for: sid) else {
248	      return completion(.failed(.other("That workroom is no longer available.")))
249	    }
250	    // Fixture mode swaps the WRITER — `FixtureVCSWriter` rather than spawning git or jj, since the
251	    // fixture paths aren't real repos and a live write would only ever fail. Only the writer: taking
252	    // an early return here instead skipped the whole store-side lane (the in-flight marks, the
253	    // captured-sid refresh), so the one tier that drives this code end to end exercised none of it.
254	    // `refreshStatus(for:)` already no-ops under the fixture, so the rest is safe to run.
255	    let root = item.projectRoot
256	    // Refuse outright rather than queue behind another write (commit/fetch/push/pull, this window
257	    // or another) on the same project root — see `isWritingProject`'s doc for why queuing into
258	    // `JJSnapshotGate` here would risk racing it past the gate's own wedge-detection ceiling.
259	    guard !isWritingProject(root) else {
260	      return completion(.failed(.locked(nil)))
261	    }
262	    committingTargets.insert(sid)
263	    committingProjectRoots[root, default: 0] += 1
264	    beginWrite(projectRoot: root)
265	    Task { [weak self] in
266	      let result: VCSCommitResult
267	      if UITestFixture.isActive {
268	        result = await FixtureVCSWriter().commit(
269	          path: item.path, projectRoot: root, request: request)
270	      } else {
271	        do {
272	          let writer = try VCS.writer(for: URL(fileURLWithPath: item.path, isDirectory: true))
273	          result = await writer.commit(path: item.path, projectRoot: root, request: request)
274	        } catch {
275	          result = .failed(.other("\(error)"))
276	        }
